handleFormSubmit(e) {
    e.preventDefault();

    const form = e.target;
    const action = form.getAttribute('action');
    if (!action || action === '#') return;

    const submitBtn = form.querySelector('button[type="submit"]');
    const originalHTML = submitBtn.innerHTML;
    submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin mr-2"></i>Sending...';
    submitBtn.disabled = true;

    fetch(action, {
        method: 'POST',
        body: new FormData(form),
        headers: { 'Accept': 'application/json' }
    })
    .then(response => {
        if (!response.ok) throw new Error('Form submission failed');

        submitBtn.innerHTML = '<i class="fas fa-check mr-2"></i>Sent Successfully!';
        submitBtn.style.background = '#10b981';
        form.reset();
        Utils.showNotification("Thank you! We'll get back to you soon.", 'success');

        setTimeout(() => {
            submitBtn.innerHTML = originalHTML;
            submitBtn.disabled = false;
            submitBtn.style.background = '';
        }, 3000);
    })
    .catch(error => {
        console.error('Error:', error);

        submitBtn.innerHTML = '<i class="fas fa-exclamation-triangle mr-2"></i>Error! Try Again';
        submitBtn.style.background = '#ef4444';
        Utils.showNotification('There was an error sending your message.', 'error');

        setTimeout(() => {
            submitBtn.innerHTML = originalHTML;
            submitBtn.disabled = false;
            submitBtn.style.background = '';
        }, 3000);
    });
}

