         document.getElementById('phone').addEventListener('input', function(e) {
             let value = e.target.value.replace(/\D/g, '');
             if (value.length > 0) {
                 // Format as +XX XXX XXX XXXX
                 if (value.length <= 3) {
                     value = '+' + value;
                 } else if (value.length <= 6) {
                     value = '+' + value.slice(0, 3) + ' ' + value.slice(3);
                 } else if (value.length <= 9) {
                     value = '+' + value.slice(0, 3) + ' ' + value.slice(3, 6) + ' ' + value.slice(6);
                 } else {
                     value = '+' + value.slice(0, 3) + ' ' + value.slice(3, 6) + ' ' + value.slice(6, 9) + ' ' + value.slice(9, 13);
                 }
             }
             e.target.value = value;
         });

         // Character counter for message
         const messageField = document.getElementById('message');
         const maxLength = 1000;

         // Create character counter element
         const charCounter = document.createElement('div');
         charCounter.className = 'text-sm text-gray-500 mt-1';
         charCounter.textContent = `0 / ${maxLength} characters`;
         messageField.parentNode.appendChild(charCounter);

         messageField.addEventListener('input', function(e) {
             const currentLength = e.target.value.length;
             const remaining = maxLength - currentLength;

             // Update character counter
             charCounter.textContent = `${currentLength} / ${maxLength} characters`;

             // Change color based on remaining characters
             if (remaining < 100) {
                 charCounter.style.color = '#ef4444';
             } else if (remaining < 200) {
                 charCounter.style.color = '#f59e0b';
             } else {
                 charCounter.style.color = '#6b7280';
             }

             // Prevent typing if max length reached
             if (currentLength >= maxLength) {
                 e.target.value = e.target.value.slice(0, maxLength);
             }
         });
