         // Hero Section Animations - Optimized
         gsap.from('.hero-title', {
             duration: 1,
             y: 50,
             opacity: 0,
             ease: "power2.out"
         });

         gsap.from('.floating-shape', {
             duration: 1.2,
             scale: 0,
             opacity: 0,
             stagger: 0.1,
             ease: "back.out(1.4)"
         });

         // Service Cards Animation - Optimized
         gsap.from('.service-card', {
             duration: 0.8,
             y: 30,
             opacity: 0,
             stagger: 0.05,
             ease: "power2.out",
             scrollTrigger: {
                 trigger: '#services',
                 start: "top 85%"
             }
         });

         // Stats Counter Animation
         const counters = document.querySelectorAll('.stat-card .text-4xl');
         counters.forEach(counter => {
             const target = parseInt(counter.textContent);
             const increment = target / 100;

             ScrollTrigger.create({
                 trigger: counter,
                 start: "top 80%",
                 onEnter: () => {
                     let current = 0;
                     const updateCounter = () => {
                         if (current < target) {
                             current += increment;
                             counter.textContent = Math.ceil(current) + (counter.textContent.includes('+') ? '+' : '') + (counter.textContent.includes('%') ? '%' : '') + (counter.textContent.includes('/') ? '/7' : '');
                             requestAnimationFrame(updateCounter);
                         } else {
                             counter.textContent = target + (counter.textContent.includes('+') ? '+' : '') + (counter.textContent.includes('%') ? '%' : '') + (counter.textContent.includes('/') ? '/7' : '');
                         }
                     };
                     updateCounter();
                 }
             });
         });

         // Parallax Effect - Optimized (disabled for better performance)
