 <!DOCTYPE html>
 <html lang="en">
 <head>
     <meta charset="utf-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <meta name="description" content="Lanka Global Access Consultancy - Your trusted partner in visa and immigration consulting." />
     <meta name="author" content="Lanka Global Access" />
     <title>Lanka Global Access - Professional Visa & Immigration Services</title>

     <link rel="shortcut icon" href="images/ico/favicon.ico" />

     <!-- Shared design system -->
     <link rel="stylesheet" href="assets/css/site.css" />

     <!-- Preload critical resources -->
     <link rel="preload" href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&family=Playfair+Display:wght@400;600;700&display=swap" as="style" onload="this.onload=null;this.rel='stylesheet'">
     <noscript><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&family=Playfair+Display:wght@400;600;700&display=swap"></noscript>

     <!-- Modern CSS Framework -->
     <script src="https://cdn.tailwindcss.com"></script>

     <!-- Font Awesome Icons - Load only essential icons -->
     <link rel="preload" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" as="style" onload="this.onload=null;this.rel='stylesheet'">
     <noscript><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"></noscript>

     <!-- GSAP Animation Library - Load only essential plugins -->
     <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
     <script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js"></script>

     <!-- AOS Animation Library -->
     <link rel="preload" href="https://unpkg.com/aos@2.3.1/dist/aos.css" as="style" onload="this.onload=null;this.rel='stylesheet'">
     <noscript><link rel="stylesheet" href="https://unpkg.com/aos@2.3.1/dist/aos.css"></noscript>
     <script src="https://unpkg.com/aos@2.3.1/dist/aos.js"></script>

     <style>
         :root {
             --primary-color: #1e40af;
             --secondary-color: #3b82f6;
             --accent-color: #f59e0b;
             --dark-color: #1f2937;
             --light-color: #f8fafc;
             --gradient-primary: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
             --gradient-secondary: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
             --gradient-accent: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%);
         }

         * {
             box-sizing: border-box;
             margin: 0;
             padding: 0;
         }

         html {
             scroll-behavior: smooth;
             overflow-x: hidden;
         }

         body {
             font-family: 'Poppins', sans-serif;
             line-height: 1.6;
             color: var(--dark-color);
             overflow-x: hidden;
         }

         .font-display {
             font-family: 'Playfair Display', serif;
         }

         /* Custom Scrollbar */
         ::-webkit-scrollbar {
             width: 8px;
         }

         ::-webkit-scrollbar-track {
             background: #f1f1f1;
         }

         ::-webkit-scrollbar-thumb {
             background: var(--primary-color);
             border-radius: 4px;
         }

         ::-webkit-scrollbar-thumb:hover {
             background: var(--secondary-color);
         }

         /* Header Styles */
         .header {
             background: rgba(255, 255, 255, 0.95);
             backdrop-filter: blur(20px);
             border-bottom: 1px solid rgba(255, 255, 255, 0.2);
             transition: all 0.3s ease;
         }

         .header.scrolled {
             background: rgba(255, 255, 255, 0.98);
             box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
         }

         .nav-link {
             position: relative;
             transition: all 0.3s ease;
         }

         .nav-link::after {
             content: '';
             position: absolute;
             bottom: -5px;
             left: 0;
             width: 0;
             height: 2px;
             background: var(--gradient-primary);
             transition: width 0.3s ease;
         }

         .nav-link:hover::after {
             width: 100%;
         }

         /* Hero Slideshow Styles */
         .hero-slideshow {
             position: relative;
             width: 100%;
             height: 100vh;
             overflow: hidden;
         }

         .hero-slide {
             position: absolute;
             top: 0;
             left: 0;
             width: 100%;
             height: 100%;
             opacity: 0;
             transition: opacity 1s ease-in-out;
             display: flex;
             align-items: center;
             justify-content: center;
             background-size: cover !important;
             background-position: center !important;
             background-repeat: no-repeat !important;
         }

         .hero-slide.active {
             opacity: 1;
         }

         /* Background image zoom effect on slide change */
         .hero-slide::before {
             content: '';
             position: absolute;
             top: 0;
             left: 0;
             right: 0;
             bottom: 0;
             background: inherit;
             background-size: cover;
             background-position: center;
             transition: transform 8s ease-in-out;
             z-index: -1;
         }

         .hero-slide.active::before {
             transform: scale(1.1);
         }

         /* Overlay for better text readability */
         .hero-slide .bg-black {
             z-index: 1;
         }

         /* Slide Navigation */
         .slide-dot {
             cursor: pointer;
             transition: all 0.3s ease;
         }

         .slide-dot.active {
             background: white !important;
             transform: scale(1.2);
         }

         .slide-nav {
             cursor: pointer;
             opacity: 0.7;
             transition: all 0.3s ease;
         }

         .slide-nav:hover {
             opacity: 1;
             transform: scale(1.1);
         }

         /* Floating Shapes - Optimized */
         .floating-shape {
             position: absolute;
             background: rgba(255, 255, 255, 0.1);
             border-radius: 50%;
             animation: float 6s ease-in-out infinite;
             pointer-events: none;
         }

         .shape-1 { width: 80px; height: 80px; top: 20%; left: 10%; animation-delay: 0s; }
         .shape-2 { width: 120px; height: 120px; top: 60%; right: 10%; animation-delay: 2s; }
         .shape-3 { width: 60px; height: 60px; bottom: 20%; left: 20%; animation-delay: 4s; }
         .shape-4 { width: 100px; height: 100px; top: 40%; right: 20%; animation-delay: 1s; }
         .shape-5 { width: 40px; height: 40px; bottom: 40%; right: 30%; animation-delay: 3s; }

         @keyframes float {
             0%, 100% { transform: translateY(0px) rotate(0deg); }
             50% { transform: translateY(-20px) rotate(180deg); }
         }

         /* Service Cards */
         .service-card {
             background: white;
             border-radius: 20px;
             padding: 2.5rem;
             box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
             transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
             position: relative;
             overflow: hidden;
             display: block !important;
             visibility: visible !important;
             opacity: 1 !important;
         }

         .service-card::before {
             content: '';
             position: absolute;
             top: 0;
             left: 0;
             width: 100%;
             height: 4px;
             background: var(--gradient-primary);
             transform: scaleX(0);
             transition: transform 0.3s ease;
         }

         .service-card:hover::before {
             transform: scaleX(1);
         }

         .service-card:hover {
             transform: translateY(-10px) scale(1.02);
             box-shadow: 0 30px 60px rgba(0, 0, 0, 0.15);
         }

         .service-icon {
             width: 80px;
             height: 80px;
             background: var(--gradient-primary);
             border-radius: 20px;
             display: flex;
             align-items: center;
             justify-content: center;
             margin-bottom: 1.5rem;
             transition: all 0.3s ease;
         }

         .service-card:hover .service-icon {
             transform: rotate(360deg) scale(1.1);
         }

         /* Country Cards */
         .country-card {
             background: white;
             border-radius: 20px;
             overflow: hidden;
             box-shadow: 0 15px 35px rgba(0, 0, 0, 0.1);
             transition: all 0.4s ease;
             position: relative;
         }

         .country-card:hover {
             transform: translateY(-10px);
             box-shadow: 0 25px 50px rgba(0, 0, 0, 0.15);
         }

         .country-image {
             height: 250px;
             background-size: cover;
             background-position: center;
             position: relative;
             overflow: hidden;
         }

         .country-image::before {
             content: '';
             position: absolute;
             top: 0;
             left: 0;
             right: 0;
             bottom: 0;
             background: linear-gradient(45deg, rgba(0,0,0,0.3), transparent);
             transition: all 0.3s ease;
         }

         .country-card:hover .country-image::before {
             background: linear-gradient(45deg, rgba(0,0,0,0.1), transparent);
         }

         /* Stats Section */
         .stats-section {
             background: var(--gradient-secondary);
             position: relative;
             overflow: hidden;
         }

         .stat-card {
             background: rgba(255, 255, 255, 0.1);
             backdrop-filter: blur(10px);
             border-radius: 20px;
             padding: 2rem;
             text-align: center;
             border: 1px solid rgba(255, 255, 255, 0.2);
         }

         /* Contact Section */
         .contact-card {
             background: white;
             border-radius: 20px;
             padding: 2.5rem;
             box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
             transition: all 0.3s ease;
         }

         .contact-card:hover {
             transform: translateY(-5px);
             box-shadow: 0 30px 60px rgba(0, 0, 0, 0.15);
         }

         /* WhatsApp Float */
         .whatsapp-float {
             position: fixed;
             bottom: 30px;
             right: 30px;
             width: 70px;
             height: 70px;
             background: #25D366;
             border-radius: 50%;
             display: flex;
             align-items: center;
             justify-content: center;
             box-shadow: 0 10px 30px rgba(37, 211, 102, 0.3);
             transition: all 0.3s ease;
             z-index: 1000;
             animation: pulse 2s infinite;
         }

         .whatsapp-float:hover {
             transform: scale(1.1);
             box-shadow: 0 15px 40px rgba(37, 211, 102, 0.4);
         }

         @keyframes pulse {
             0% { box-shadow: 0 10px 30px rgba(37, 211, 102, 0.3); }
             50% { box-shadow: 0 10px 30px rgba(37, 211, 102, 0.6); }
             100% { box-shadow: 0 10px 30px rgba(37, 211, 102, 0.3); }
         }

         /* Loading Animation - Optimized */
         .loader {
             position: fixed;
             top: 0;
             left: 0;
             width: 100%;
             height: 100%;
             background: white;
             display: flex;
             align-items: center;
             justify-content: center;
             z-index: 9999;
             transition: opacity 0.3s ease;
         }

         .loader.hidden {
             opacity: 0;
             pointer-events: none;
         }

         .spinner {
             width: 40px;
             height: 40px;
             border: 3px solid #f3f3f3;
             border-top: 3px solid var(--primary-color);
             border-radius: 50%;
             animation: spin 0.8s linear infinite;
         }

         @keyframes spin {
             0% { transform: rotate(0deg); }
             100% { transform: rotate(360deg); }
         }

         /* Mobile Menu Styles */
         #mobile-menu {
             background: white !important;
             backdrop-filter: none !important;
             height: 100vh !important;
             min-height: 100vh !important;
             max-height: 100vh !important;
             overflow-y: auto;
         }

         #mobile-menu .bg-white {
             background: white !important;
         }

         #mobile-menu a {
