             scale: 0,
             opacity: 0,
             stagger: 0.1,
             ease: "back.out(1.4)"
         });

         // Service Cards Animation - Optimized
         gsap.from('.service-card', {
             duration: 0.8,
             y: 30,
             opacity: 0,
             stagger: 0.05,
             ease: "power2.out",
             scrollTrigger: {
                 trigger: '#services',
                 start: "top 85%"
             }
         });

         // Stats Counter Animation
         const counters = document.querySelectorAll('.stat-card .text-4xl');
         counters.forEach(counter => {
             const target = parseInt(counter.textContent);
             const increment = target / 100;

             ScrollTrigger.create({
                 trigger: counter,
                 start: "top 80%",
                 onEnter: () => {
                     let current = 0;
                     const updateCounter = () => {
                         if (current < target) {
                             current += increment;
                             counter.textContent = Math.ceil(current) + (counter.textContent.includes('+') ? '+' : '') + (counter.textContent.includes('%') ? '%' : '') + (counter.textContent.includes('/') ? '/7' : '');
                             requestAnimationFrame(updateCounter);
                         } else {
                             counter.textContent = target + (counter.textContent.includes('+') ? '+' : '') + (counter.textContent.includes('%') ? '%' : '') + (counter.textContent.includes('/') ? '/7' : '');
                         }
                     };
                     updateCounter();
                 }
             });
         });

         // Parallax Effect - Optimized (disabled for better performance)
         // gsap.to('.floating-shapes', {
         //     yPercent: -50,
         //     ease: "none",
         //     scrollTrigger: {
         //         trigger: '.hero-section',
         //         start: "top bottom",
         //         end: "bottom top",
         //         scrub: true
         //     }
         // });

         // Hero Slideshow Functionality
         class HeroSlideshow {
             constructor() {
                 this.currentSlide = 0;
                 this.slides = document.querySelectorAll('.hero-slide');
                 this.dots = document.querySelectorAll('.slide-dot');
                 this.prevBtn = document.getElementById('prev-slide');
                 this.nextBtn = document.getElementById('next-slide');
                 this.totalSlides = this.slides.length;
                 this.autoPlayInterval = null;
                 this.autoPlayDelay = 4000; // 4 seconds

                 this.init();
             }

             init() {
                 this.bindEvents();
                 this.startAutoPlay();
                 this.updateSlide();
             }

             bindEvents() {
                 // Dot navigation
                 this.dots.forEach((dot, index) => {
                     dot.addEventListener('click', () => {
                         this.goToSlide(index);
                     });
                 });

                 // Arrow navigation
                 this.prevBtn.addEventListener('click', () => {
                     this.prevSlide();
                 });

                 this.nextBtn.addEventListener('click', () => {
                     this.nextSlide();
                 });

                 // Pause autoplay on hover
                 const slideshow = document.querySelector('.hero-slideshow');
                 slideshow.addEventListener('mouseenter', () => {
                     this.stopAutoPlay();
                 });

                 slideshow.addEventListener('mouseleave', () => {
                     this.startAutoPlay();
                 });

                 // Keyboard navigation
                 document.addEventListener('keydown', (e) => {
                     if (e.key === 'ArrowLeft') {
                         this.prevSlide();
                     } else if (e.key === 'ArrowRight') {
                         this.nextSlide();
                     }
                 });
             }

             goToSlide(index) {
                 // Remove active class from current slide and dot
                 this.slides[this.currentSlide].classList.remove('active');
                 this.dots[this.currentSlide].classList.remove('active');

                 // Update current slide
                 this.currentSlide = index;

                 // Add active class to new slide and dot
                 this.slides[this.currentSlide].classList.add('active');
                 this.dots[this.currentSlide].classList.add('active');

                 // Reset autoplay timer
                 this.resetAutoPlay();
             }

             nextSlide() {
                 const nextIndex = (this.currentSlide + 1) % this.totalSlides;
                 this.goToSlide(nextIndex);
             }

             prevSlide() {
                 const prevIndex = (this.currentSlide - 1 + this.totalSlides) % this.totalSlides;
                 this.goToSlide(prevIndex);
             }

             updateSlide() {
                 this.slides.forEach((slide, index) => {
                     if (index === this.currentSlide) {
                         slide.classList.add('active');
                     } else {
                         slide.classList.remove('active');
                     }
                 });

                 this.dots.forEach((dot, index) => {
                     if (index === this.currentSlide) {
                         dot.classList.add('active');
                     } else {
                         dot.classList.remove('active');
                     }
                 });
             }

             startAutoPlay() {
                 this.autoPlayInterval = setInterval(() => {
                     this.nextSlide();
                 }, this.autoPlayDelay);
             }

             stopAutoPlay() {
                 if (this.autoPlayInterval) {
                     clearInterval(this.autoPlayInterval);
                     this.autoPlayInterval = null;
                 }
             }

             resetAutoPlay() {
                 this.stopAutoPlay();
                 this.startAutoPlay();
             }
         }

         // Initialize slideshow when DOM is loaded
         document.addEventListener('DOMContentLoaded', () => {
             new HeroSlideshow();
         });
     </script>
