import os, re
from urllib.parse import urlparse, unquote

root = '.'
html_files = []
for dp, dns, fns in os.walk(root):
    if any(s in dp for s in ('.git', 'node_modules', '.opencode')): continue
    for fn in fns:
        if fn.endswith('.html'):
            html_files.append(os.path.join(dp, fn))

broken, ok = [], 0
for hf in sorted(html_files):
    src = open(hf).read()
    for m in re.finditer(r'''(?:href|src)="([^"]+)"''', src):
        url = m.group(1)
        if url.startswith(('http', 'mailto:', 'tel:', 'data:', '#', 'javascript:')): continue
        path = unquote(urlparse(url).path).split('?')[0].split('#')[0]
        if not path: continue
        target = os.path.normpath(os.path.join(os.path.dirname(hf), path))
        if os.path.exists(target): ok += 1
        else: broken.append(f'{hf}: {url}')

# also check image refs in CSS background-image inline styles
for hf in sorted(html_files):
    src = open(hf).read()
    for m in re.finditer(r'''background-image:\s*url\('([^']+)'\)''', src):
        path = unquote(urlparse(m.group(1)).path)
        target = os.path.normpath(os.path.join(os.path.dirname(hf), path))
        if os.path.exists(target): ok += 1
        else: broken.append(f'{hf}: {m.group(1)} (css bg)')

print(f'{len(html_files)} HTML files, {ok} valid local refs')
print('BROKEN:' if broken else 'NO BROKEN LINKS')
for b in broken: print(' ', b)
EOF

